-- SECURITY DEFINER; API roles that may call it: service_role
CREATE OR REPLACE FUNCTION public.invoice_terms(p_reward uuid)
 RETURNS TABLE(payment jsonb, currency text, amount numeric, fx numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; v_pay jsonb; v_ccy text; v_amt numeric; v_fx numeric;
begin
  select * into r from public.rewards where id = p_reward;
  if r is null then return; end if;

  v_pay := public.payment_snapshot(r.creator_id, r.currency);
  -- The currency the money will land in. A creator who has told us they bank in
  -- euros gets a euro invoice even when the prize was written in pounds.
  v_ccy := coalesce(nullif(v_pay ->> 'currency', ''), r.currency, 'GBP');
  v_amt := public.fx_convert(r.amount, coalesce(r.currency, 'GBP'), v_ccy);
  v_fx  := case when v_ccy = coalesce(r.currency, 'GBP') then null
                else round(v_amt / nullif(r.amount, 0), 4) end;
  return query select v_pay, v_ccy, v_amt, v_fx;
end $function$;
